select *
  from batch.trigger_misfire_pending
 where tenant_id = #{tenantId}
   and workflow_definition_id = #{workflowDefinitionId}
   and scheduled_fire_time = #{scheduledFireTime}
 order by id desc
 limit 1

select *
  from batch.trigger_misfire_pending
 where tenant_id = #{tenantId}
   and status = #{status}
 order by detected_at desc
 limit #{limit}

mapper.update:
update batch.trigger_misfire_pending set status = #{targetStatus}, approved_by = #{approvedBy}, approved_at = now(),
rejection_reason = #{rejectionReason},
updated_at = now() where id = #{id} and status = #{expectedStatus}

update batch.trigger_misfire_pending
   set status = #{targetStatus},
       updated_at = now()
 where status = #{expectedStatus}
   and expires_at < #{now}
